// spec: specs/delivery.md §12 · кейс .qa/tests/delivery/dlv-16-delivery-note-1024-layout.md
// seed: tests/seed.admin.spec.ts
// #b4cd60 (באג, עבר QA 28.10, commit 1b87390): תעודת משלוח на 1024 с меню — таблица товаров была 245px, цены «₪1.»/«00», «כמות» вылезала.
//   «מה רצוי»: на 1024 — цены/суммы в одну строку, заголовки не выходят из ячеек (F-22 / D-09 «התצוגה מתאימה את עצמה לגודל המסך»).
//   Решение программиста (принято): <1280 панель «שיוך נהג ומסלול» НАД תעודה; таблица переходит в ряды по СВОЕЙ ширине <576px.
//   Измерено 28.10: 1024+меню — таблица 585, 5 колонок, штрихкод 150px; 1280+меню — 501 → ряды; 1354/1355+меню — 575/576;
//   без меню 718/719 — 575/576; печать — без панели.
// Данные — существующие заказы, только чтение: #504 (есть панель שיוך), #663 (נדחתה, без панели, 13 строк). → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const NOTES = { 504: '6f797bf5-1ef8-44eb-8ad5-073e0b0f341e', 663: 'f7287a79-a4a9-45dc-a0f0-6f90ca7c8da6' } as const;
type No = keyof typeof NOTES;
const PANEL = 'שיוך נהג ומסלול';

async function openNote(page: Page, no: No) {
  await page.goto(`/delivery/${NOTES[no]}`);
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('svg[data-barcode]').first()).toBeAttached({ timeout: 20_000 });
  if (no === 504) await expect(page.getByRole('heading', { name: PANEL })).toBeVisible({ timeout: 20_000 });
}

async function setSidebar(page: Page, open: boolean) {
  const collapse = page.getByRole('button', { name: 'כיווץ תפריט הצד' });
  const expand = page.getByRole('button', { name: 'הרחבת תפריט הצד' });
  if (open && (await expand.isVisible())) await expand.click();
  if (!open && (await collapse.isVisible())) await collapse.click();
  await expect(open ? collapse : expand).toBeVisible();
}

async function resize(page: Page, w: number) {
  await page.setViewportSize({ width: w, height: 900 });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
}

/** Экранная таблица товаров: ширина, видимые колонки, заголовки (текст vs ячейка), цены (число строк текста), штрихкоды, панель. */
const measure = (page: Page, panelTitle: string) => page.evaluate((panelTitle) => {
  const t = [...document.querySelectorAll('table')].find((x) => !x.classList.contains('pd-table') && x.checkVisibility()) as HTMLTableElement;
  const rect = (e: Element) => e.getBoundingClientRect();
  const textW = (e: Element) => { const r = document.createRange(); r.selectNodeContents(e); return r.getBoundingClientRect().width; };
  const lines = (e: Element) => {
    const r = document.createRange(); r.selectNodeContents(e);
    return new Set([...r.getClientRects()].filter((q) => q.width > 0).map((q) => Math.round(q.top))).size;
  };
  const heads = [...t.tHead!.rows[0].cells].filter((c) => c.checkVisibility()).map((c) => {
    const cs = getComputedStyle(c);
    return { text: c.textContent!.trim(), textW: textW(c), contentW: c.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight), sw: c.scrollWidth, cw: c.clientWidth };
  });
  const prices = [...t.tBodies[0].querySelectorAll('bdi')].filter((b) => /₪/.test(b.textContent!) && b.checkVisibility())
    .map((b) => ({ text: b.textContent!.trim(), lines: lines(b) }));
  const rows = [...t.tBodies[0].rows].map((r) => {
    const vis = [...r.querySelectorAll('svg[data-barcode]')].filter((s) => s.checkVisibility() && s.getBoundingClientRect().width > 0);
    return { name: (r.cells[0].firstChild?.textContent ?? '').trim(), barcodes: vis.length, bcW: vis.map((s) => s.getBoundingClientRect().width) };
  });
  const ph = [...document.querySelectorAll('h1,h2,h3,h4')].find((h) => h.textContent!.trim() === panelTitle && (h as HTMLElement).checkVisibility());
  const tr = rect(t);
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, tw: tr.width, tTop: tr.top, tLeft: tr.left, tRight: tr.right,
    cols: heads.length, heads, prices, rows,
    panel: ph ? { top: rect(ph).top, bottom: rect(ph).bottom, left: rect(ph).left, right: rect(ph).right } : null,
  };
}, panelTitle);
type M = Awaited<ReturnType<typeof measure>>;

/** «מה רצוי»: цены/суммы в одну строку, заголовки в своих ячейках, без прокрутки вбок; 1 видимый штрихкод в строке с ним. */
function expectReadable(m: M, tag: string) {
  expect(m.prices.length, `${tag}: есть цены`).toBeGreaterThan(0);
  for (const p of m.prices) expect(p.lines, `${tag}: «${p.text}» — в одну строку (было «₪1.» / «00»)`).toBe(1);
  for (const h of m.heads) {
    expect(h.textW, `${tag}: заголовок «${h.text}» (${h.textW.toFixed(1)}px) помещается в ячейку (${h.contentW.toFixed(1)}px)`).toBeLessThanOrEqual(h.contentW + 0.5);
    expect(h.sw, `${tag}: заголовок «${h.text}» без переполнения`).toBeLessThanOrEqual(h.cw);
  }
  expect(m.docSW, `${tag}: без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  for (const r of m.rows) expect(r.barcodes, `${tag}: «${r.name}» — не больше 1 видимого штрихкода`).toBeLessThanOrEqual(1);
}

function expectMode(m: M, tag: string) {
  const wide = m.tw >= 576;
  expect(m.cols, `${tag}: таблица ${Math.round(m.tw)}px → ${wide ? '5 колонок' : 'ряды (3 колонки)'}`).toBe(wide ? 5 : 3);
}

test.describe('delivery — תעודת משלוח ברוחב 1024: טבלת הפריטים רחבה, מחירים בשורה אחת (#b4cd60)', () => {
  test('1024 עם תפריט: פאנל «שיוך נהג ומסלול» מעל התעודה, טבלה ≥576px ו-5 עמודות, מחירים בשורה אחת, כותרות בתוך התא, ברקוד רחב #b4cd60 @desktop @delivery @prod-safe', async ({ page }) => {
    for (const no of [504, 663] as No[]) {
      await page.setViewportSize({ width: 1024, height: 900 });
      await openNote(page, no);
      await setSidebar(page, true);
      const m = await measure(page, PANEL);
      const tag = `#${no} 1024+меню`;
      expect(m.tw, `${tag}: таблица шире 576 (было 245)`).toBeGreaterThanOrEqual(576);
      expect(m.cols, `${tag}: 5 колонок`).toBe(5);
      expect(m.heads.map((h) => h.text)).toEqual(['שם פריט', 'מק"ט', 'כמות', 'מחיר יחידה', 'סה״כ']);
      expectReadable(m, tag);
      const withBc = m.rows.filter((r) => r.barcodes === 1);
      expect(withBc.length, `${tag}: есть строки со штрихкодом`).toBeGreaterThan(0);
      for (const r of withBc) expect(r.bcW[0], `${tag}: «${r.name}» — штрихкод не крошечный (было 58px)`).toBeGreaterThanOrEqual(100);
      if (no === 504) {
        expect(m.panel, `${tag}: панель «${PANEL}» видна`).not.toBeNull();
        expect(m.panel!.bottom, `${tag}: панель над תעודה`).toBeLessThanOrEqual(m.tTop);
      } else {
        expect(m.panel, `${tag}: у отклонённого панели нет (dlv-14)`).toBeNull();
      }
    }
  });

  test('1440: הפאנל ליד התעודה; 1279: מעל; בשתיהן אין שבירת מחירים #b4cd60 @desktop @delivery @prod-safe', async ({ page }) => {
    await openNote(page, 504);
    await setSidebar(page, true);
    let m = await measure(page, PANEL);
    expect(m.panel, '1440: панель видна').not.toBeNull();
    expect(m.panel!.top, '1440: панель сбоку — начинается выше конца таблицы').toBeLessThan(m.tTop);
    expect(m.panel!.right <= m.tLeft + 1 || m.panel!.left >= m.tRight - 1, '1440: панель сбоку от таблицы, не над ней').toBe(true);
    expectMode(m, '#504 1440');
    expectReadable(m, '#504 1440');
    await resize(page, 1279);
    m = await measure(page, PANEL);
    expect(m.panel!.bottom, '1279: панель над תעודה').toBeLessThanOrEqual(m.tTop);
    expectMode(m, '#504 1279');
    expectReadable(m, '#504 1279');
  });

  test('ריבוי שורות לפי רוחב הטבלה (<576px): 1280 עם תפריט — שורות; 1354/1355 עם תפריט ו-718/719 בלי תפריט — הגבול; תמיד קריא #b4cd60 @desktop @delivery @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await openNote(page, 663);
    await setSidebar(page, true);
    await resize(page, 1280);
    let m = await measure(page, PANEL);
    expect(m.tw, '1280+меню: таблица уже 576 (≈501)').toBeLessThan(576);
    expect(m.cols, '1280+меню: ряды — 3 колонки').toBe(3);
    expectReadable(m, '#663 1280+меню');
    const seen: Record<number, number> = {};
    for (const w of [1354, 1355]) {
      await resize(page, w);
      m = await measure(page, PANEL);
      seen[w] = m.tw;
      expectMode(m, `#663 ${w}+меню`);
      expectReadable(m, `#663 ${w}+меню`);
    }
    expect(seen[1354] < 576 && seen[1355] >= 576, `граница ряды/колонки по таблице: 1354→${seen[1354]}, 1355→${seen[1355]}`).toBe(true);
    await setSidebar(page, false);
    for (const w of [1024, 719, 718, 640, 639]) {
      await resize(page, w);
      m = await measure(page, PANEL);
      expectMode(m, `#663 ${w} без меню`);
      expectReadable(m, `#663 ${w} без меню`);
      seen[w] = m.tw;
    }
    expect(seen[718] < 576 && seen[719] >= 576, `граница без меню: 718→${seen[718]}, 719→${seen[719]}`).toBe(true);
  });

  test('הדפסה ב-1024: בלי פאנל «שיוך נהג ומסלול», טבלת ההדפסה גלויה #b4cd60 @desktop @delivery @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 1024, height: 900 });
    await openNote(page, 504);
    await page.emulateMedia({ media: 'print' });
    await expect(page.getByRole('heading', { name: PANEL })).toBeHidden();
    await expect(page.locator('table.pd-table')).toBeVisible();
    const pdf = await page.pdf({ format: 'A4', printBackground: true });
    expect(pdf.subarray(0, 5).toString(), 'PDF A4 сформирован').toBe('%PDF-');
    await page.emulateMedia({ media: 'screen' });
  });
});
